INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ffa4dd3b-46d4-5076-87b0-1823bacbd173', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which OSPF LSA type is generated by an ASBR and advertises external routes?$$::text, $$[{"id": "A", "text": "Type 1", "is_correct": false}, {"id": "B", "text": "Type 2", "is_correct": false}, {"id": "C", "text": "Type 3", "is_correct": false}, {"id": "D", "text": "Type 5", "is_correct": true}]$$::jsonb, $$Type 5 LSAs are external LSAs originated by ASBRs to advertise routes external to the OSPF domain.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, '609ea95831a3d60f', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('12e0cb67-711e-5c29-a46e-f8e34d3a878d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which OSPF area type blocks Type 5 external LSAs but allows a default route?$$::text, $$[{"id": "A", "text": "Standard area", "is_correct": false}, {"id": "B", "text": "Stub area", "is_correct": true}, {"id": "C", "text": "Backbone area", "is_correct": false}, {"id": "D", "text": "NSSA", "is_correct": false}]$$::jsonb, $$Stub areas block Type 5 external LSAs and use a default route. NSSA blocks Type 5 but allows Type 7 external LSAs.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, '314eb4dcfa6cc3cf', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4985e045-5bf0-5987-a719-87dfdf53999f', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which command displays OSPF link-state database details?$$::text, $$[{"id": "A", "text": "show ospf neighbor", "is_correct": false}, {"id": "B", "text": "show ospf database", "is_correct": true}, {"id": "C", "text": "show ospf interface", "is_correct": false}, {"id": "D", "text": "show route ospf", "is_correct": false}]$$::jsonb, $$'show ospf database' displays the OSPF LSDB, including LSA types and details.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, '44207724d53dc7e8', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2d0fe398-473e-5787-9e20-3b6fb9624916', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$In OSPFv3, which address is used as the next-hop for inter-area routes?$$::text, $$[{"id": "A", "text": "IPv4 address of the ABR", "is_correct": false}, {"id": "B", "text": "Link-local address", "is_correct": true}, {"id": "C", "text": "Global unicast address", "is_correct": false}, {"id": "D", "text": "Loopback address", "is_correct": false}]$$::jsonb, $$OSPFv3 uses IPv6 link-local addresses as next-hops, unlike OSPFv2 which uses IPv4 addresses.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, '9ed0f19ba17b69f9', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8fd19afa-a072-5e09-ab1a-06c075a2cc2e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which OSPF network type does not elect a DR/BDR?$$::text, $$[{"id": "A", "text": "Broadcast", "is_correct": false}, {"id": "B", "text": "NBMA", "is_correct": false}, {"id": "C", "text": "Point-to-point", "is_correct": true}, {"id": "D", "text": "Multi-access", "is_correct": false}]$$::jsonb, $$Point-to-point OSPF network types do not elect a DR/BDR because only two routers exist on the segment.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, '667212daafa8c564', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a6163875-ff1c-554e-9f5e-cbabcff6a6f0', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which IS-IS PDU is used to establish and maintain adjacencies?$$::text, $$[{"id": "A", "text": "LSP", "is_correct": false}, {"id": "B", "text": "CSNP", "is_correct": false}, {"id": "C", "text": "PSNP", "is_correct": false}, {"id": "D", "text": "IIH", "is_correct": true}]$$::jsonb, $$IS-IS Hello PDUs (IIH) are used to discover and maintain adjacencies. LSPs carry link-state info, CSNPs/PSNPs synchronize databases.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$IS-IS$$::text, 10.0, '26c6b7bff9649bad', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('013f6caa-9e07-5601-b3e1-95bfd7311449', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which IS-IS area level is analogous to a non-backbone OSPF area?$$::text, $$[{"id": "A", "text": "Level 1", "is_correct": true}, {"id": "B", "text": "Level 2", "is_correct": false}, {"id": "C", "text": "Level 3", "is_correct": false}, {"id": "D", "text": "Level 1/2", "is_correct": false}]$$::jsonb, $$IS-IS Level 1 areas are similar to OSPF non-backbone areas. Level 2 forms the backbone.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$IS-IS$$::text, 10.0, 'de079ec78a20cac2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fd0f3c3-c8b3-5b3c-be7a-59db34284286', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', $$Which command enables IS-IS wide metrics on a Junos device?$$::text, $$[{"id": "A", "text": "set protocols isis level 1 wide-metrics-only", "is_correct": false}, {"id": "B", "text": "set protocols isis level 2 wide-metrics-only", "is_correct": false}, {"id": "C", "text": "set protocols isis interface all level 1 metric wide", "is_correct": false}, {"id": "D", "text": "set protocols isis level 1 wide-metrics-only and set protocols isis level 2 wide-metrics-only", "is_correct": true}]$$::jsonb, $$Wide metrics are enabled per level with 'wide-metrics-only'. They provide a larger metric range than narrow metrics.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$IS-IS$$::text, 10.0, 'aebaf9ab480997a2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('059e13f6-c819-5d04-a73c-691fd26a3dea', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which NET component identifies the area in IS-IS?$$::text, $$[{"id": "A", "text": "System ID", "is_correct": false}, {"id": "B", "text": "NSEL", "is_correct": false}, {"id": "C", "text": "Area address", "is_correct": true}, {"id": "D", "text": "Circuit ID", "is_correct": false}]$$::jsonb, $$The IS-IS NET contains the area address, system ID, and NSEL (always 0). The area address identifies the IS-IS area.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$IS-IS$$::text, 10.0, 'f87ec299ffa1118e', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('acb04205-f50c-5a7a-946f-935567567e60', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which BGP path attribute is preferred when lower?$$::text, $$[{"id": "A", "text": "Local Preference", "is_correct": false}, {"id": "B", "text": "MED", "is_correct": true}, {"id": "C", "text": "Origin", "is_correct": false}, {"id": "D", "text": "AS Path", "is_correct": false}]$$::jsonb, $$MED (Multi-Exit Discriminator) is preferred when lower. Local Preference is preferred when higher.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, 'ced9a1f3a08b46d2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('248323ee-0b83-5a3a-98fc-7f2670dd687d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which BGP feature reduces the number of iBGP peering sessions in a large AS?$$::text, $$[{"id": "A", "text": " Confederations", "is_correct": false}, {"id": "B", "text": "Route reflectors", "is_correct": true}, {"id": "C", "text": "EBGP multihop", "is_correct": false}, {"id": "D", "text": "Route damping", "is_correct": false}]$$::jsonb, $$Route reflectors reduce the full-mesh iBGP requirement by reflecting routes between clients.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, '0041f3232d39859a', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5142f20-5de0-5c64-893e-4366dd57250d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which BGP attributes prevent routing loops in route reflector deployments?$$::text, $$[{"id": "A", "text": "Originator ID and Cluster list", "is_correct": true}, {"id": "B", "text": "AS Path and Next Hop", "is_correct": false}, {"id": "C", "text": "Local Preference and MED", "is_correct": false}, {"id": "D", "text": "Origin and AS Path", "is_correct": false}]$$::jsonb, $$Route reflectors use Originator ID and Cluster List to prevent loops. Originator ID identifies the originator of a route; Cluster List records the clusters a route has passed through.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, 'a6231aa89ff29cb9', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc5d7e69-5255-5d07-a724-4163b242930d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'apply', $$Which Junos policy action prepends AS numbers to the AS Path?$$::text, $$[{"id": "A", "text": "as-path-prepend", "is_correct": true}, {"id": "B", "text": "as-path-expand", "is_correct": false}, {"id": "C", "text": "prepend-as", "is_correct": false}, {"id": "D", "text": "local-preference", "is_correct": false}]$$::jsonb, $$'as-path-prepend' adds AS numbers to the AS Path to make a route less preferred.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, '1d25bd1e265913e4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26c7c36b-d8b5-5eb3-bca1-0f516d7bf8f7', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', $$Which BGP message type is used to exchange routing updates?$$::text, $$[{"id": "A", "text": "Open", "is_correct": false}, {"id": "B", "text": "Keepalive", "is_correct": false}, {"id": "C", "text": "Update", "is_correct": true}, {"id": "D", "text": "Notification", "is_correct": false}]$$::jsonb, $$BGP Update messages carry NLRI and path attributes. Open establishes the session, Keepalive maintains it.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, '069cecd162217559', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('1d20e9b9-70fa-5fbd-8d87-2b5e776ab179', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which BGP attribute is locally significant to a router and not advertised to peers?$$::text, $$[{"id": "A", "text": "Local Preference", "is_correct": false}, {"id": "B", "text": "Weight", "is_correct": true}, {"id": "C", "text": "MED", "is_correct": false}, {"id": "D", "text": "AS Path", "is_correct": false}]$$::jsonb, $$Weight is Cisco/Junos-local and not advertised to any BGP peer. Local Preference is advertised to iBGP peers.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, 'da1d7a65d49876a4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f42ae4bf-05db-5420-b8c8-cecbc93ab0e4', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$What is the purpose of BGP route damping?$$::text, $$[{"id": "A", "text": "To prevent route reflection loops", "is_correct": false}, {"id": "B", "text": "To suppress unstable routes from being advertised", "is_correct": true}, {"id": "C", "text": "To encrypt BGP sessions", "is_correct": false}, {"id": "D", "text": "To aggregate routes", "is_correct": false}]$$::jsonb, $$Route damping penalizes flapping routes and suppresses them until they stabilize.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, '964d0aafd1cf3ede', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('2cee86d2-7b75-5f3f-a5cd-9ddec311c430', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which protocol distributes labels without requiring a full IGP topology database?$$::text, $$[{"id": "A", "text": "RSVP", "is_correct": false}, {"id": "B", "text": "LDP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]$$::jsonb, $$LDP (Label Distribution Protocol) distributes labels between directly connected neighbors using hello messages and does not require traffic engineering extensions.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, '2825f3caac0c29ac', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e1380379-2527-5286-bfed-5a17edd7cef8', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which MPLS protocol supports traffic engineering and explicit paths?$$::text, $$[{"id": "A", "text": "LDP", "is_correct": false}, {"id": "B", "text": "RSVP", "is_correct": true}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "OSPF", "is_correct": false}]$$::jsonb, $$RSVP with traffic engineering extensions supports bandwidth reservation and explicit path setup for MPLS LSPs.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, 'd0f57d7055bd2373', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('33c8baba-aa94-5e0f-8c93-7e4a4d58e866', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$What is the purpose of the MPLS label stack bottom-of-stack bit?$$::text, $$[{"id": "A", "text": "To indicate the top label", "is_correct": false}, {"id": "B", "text": "To indicate the last label in the stack", "is_correct": true}, {"id": "C", "text": "To signal PHP", "is_correct": false}, {"id": "D", "text": "To enable label stacking", "is_correct": false}]$$::jsonb, $$The bottom-of-stack (BoS) bit is set to 1 on the last label in the MPLS label stack.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, '910f83078b346bf2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('14716218-9410-55d7-80bc-d04cc2c4b39f', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which command displays MPLS label switched paths on a Junos device?$$::text, $$[{"id": "A", "text": "show mpls lsp", "is_correct": true}, {"id": "B", "text": "show route mpls", "is_correct": false}, {"id": "C", "text": "show ldp session", "is_correct": false}, {"id": "D", "text": "show rsvp neighbor", "is_correct": false}]$$::jsonb, $$'show mpls lsp' displays configured and signaled MPLS LSPs and their states.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, 'f4132a467e8f6681', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('41a63c25-7bcd-51b0-9055-c7cff86030bb', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$What does Penultimate Hop Popping (PHP) do?$$::text, $$[{"id": "A", "text": "Adds an extra label at the egress", "is_correct": false}, {"id": "B", "text": "Removes the top label one hop before the egress router", "is_correct": true}, {"id": "C", "text": "Pushes two labels at the ingress", "is_correct": false}, {"id": "D", "text": "Enables RSVP signaling", "is_correct": false}]$$::jsonb, $$PHP removes the MPLS label at the penultimate hop so the egress router processes the packet using only the underlying protocol.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, '3ba064931b29caa7', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a3cc8775-24fd-5b9c-b36d-d44d364195b7', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which address family is used to carry VPN-IPv4 routes in MP-BGP?$$::text, $$[{"id": "A", "text": "inet", "is_correct": false}, {"id": "B", "text": "inet-vpn", "is_correct": true}, {"id": "C", "text": "inet6", "is_correct": false}, {"id": "D", "text": "inet-vpnv6", "is_correct": false}]$$::jsonb, $$Junos uses the 'inet-vpn' address family for VPN-IPv4 routes in Layer 3 VPNs.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Layer 3 VPNs$$::text, 10.0, '7d0b10d6c6b235af', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bf22813c-4c26-5bd8-a334-c1935a35256f', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which routing instance type is used for MPLS Layer 3 VPNs?$$::text, $$[{"id": "A", "text": "vrf", "is_correct": true}, {"id": "B", "text": "virtual-router", "is_correct": false}, {"id": "C", "text": "forwarding", "is_correct": false}, {"id": "D", "text": "vpls", "is_correct": false}]$$::jsonb, $$VRF routing instances are used for MPLS Layer 3 VPNs, maintaining separate routing and forwarding tables per customer.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Layer 3 VPNs$$::text, 10.0, 'cc405f26bb5966b3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c04afb25-3ce0-5c06-b059-2613caa9a676', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which BGP extended community is commonly used to control VPN route distribution?$$::text, $$[{"id": "A", "text": "Route Target", "is_correct": true}, {"id": "B", "text": "Route Distinguisher", "is_correct": false}, {"id": "C", "text": "Site of Origin", "is_correct": false}, {"id": "D", "text": "Cluster ID", "is_correct": false}]$$::jsonb, $$Route Target (RT) extended communities control which VPN routes are imported and exported between VRFs.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Layer 3 VPNs$$::text, 10.0, '3a10260882bc29da', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8d612422-00ac-580b-9358-7050f94229eb', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$What is the purpose of a Route Distinguisher (RD)?$$::text, $$[{"id": "A", "text": "To encrypt VPN routes", "is_correct": false}, {"id": "B", "text": "To make overlapping customer prefixes unique in MP-BGP", "is_correct": true}, {"id": "C", "text": "To filter VPN routes", "is_correct": false}, {"id": "D", "text": "To establish MP-BGP sessions", "is_correct": false}]$$::jsonb, $$The RD is prepended to customer prefixes to create unique VPN-IPv4 addresses, allowing overlapping address spaces.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Layer 3 VPNs$$::text, 10.0, 'dcf48ccb4a59f9fd', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4cedfc2-d5ba-5710-9750-ccdd648212ad', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which interprovider VPN option uses MP-eBGP between ASBRs without storing VPN routes on ASBRs?$$::text, $$[{"id": "A", "text": "Option A", "is_correct": false}, {"id": "B", "text": "Option B", "is_correct": true}, {"id": "C", "text": "Option C", "is_correct": false}, {"id": "D", "text": "Option D", "is_correct": false}]$$::jsonb, $$Option B uses MP-eBGP between ASBRs to exchange VPN-IPv4 routes; ASBRs do not store VPN routes in VRFs.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Layer 3 VPNs$$::text, 10.0, 'bfbdc3be9e1130a7', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8bcde3d9-1d4a-57e4-a0bc-c5380c8fe9d7', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which BGP address family is used for EVPN route exchange?$$::text, $$[{"id": "A", "text": "inet-vpn", "is_correct": false}, {"id": "B", "text": "evpn", "is_correct": true}, {"id": "C", "text": "l2vpn", "is_correct": false}, {"id": "D", "text": "inet6-vpn", "is_correct": false}]$$::jsonb, $$EVPN uses the 'evpn' address family in MP-BGP to exchange MAC/IP routes.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$EVPN$$::text, 8.0, 'a12cee6fac17cc9c', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b2173d40-0f92-5483-a2ba-d47af8794ac1', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which EVPN route type is used for MAC address advertisement?$$::text, $$[{"id": "A", "text": "Type 1", "is_correct": false}, {"id": "B", "text": "Type 2", "is_correct": true}, {"id": "C", "text": "Type 3", "is_correct": false}, {"id": "D", "text": "Type 4", "is_correct": false}]$$::jsonb, $$EVPN Type 2 routes advertise MAC addresses and optionally IP addresses. Type 3 is for inclusive multicast, Type 4 for Ethernet segment routes.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$EVPN$$::text, 8.0, '335c7c794e51b767', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('258fc8a7-259e-514a-959e-5fd91963e2ae', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which VPLS signaling method uses BGP auto-discovery?$$::text, $$[{"id": "A", "text": "LDP-based VPLS", "is_correct": false}, {"id": "B", "text": "BGP-based VPLS", "is_correct": true}, {"id": "C", "text": "FEC 129 VPLS", "is_correct": false}, {"id": "D", "text": "Martini VPLS", "is_correct": false}]$$::jsonb, $$BGP-based VPLS uses BGP for auto-discovery and signaling. LDP-based VPLS uses FEC 128 and manually configured neighbors.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Layer 2 VPNs$$::text, 7.0, '9505b7cf6a3d385d', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5f58045c-81e9-5ec0-981e-4f587026f610', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which PIM mode requires a rendezvous point (RP)?$$::text, $$[{"id": "A", "text": "PIM-DM", "is_correct": false}, {"id": "B", "text": "PIM-SM", "is_correct": true}, {"id": "C", "text": "PIM-SSM", "is_correct": false}, {"id": "D", "text": "PIM-Bidir", "is_correct": false}]$$::jsonb, $$PIM Sparse Mode (PIM-SM) uses a rendezvous point for sources and receivers to find each other. SSM does not use RP.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Multicast$$::text, 7.0, '35320daa4f4c05fc', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9bd8f73-b132-5fe1-b7c0-740ba1266a4b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which multicast address range is reserved for SSM?$$::text, $$[{"id": "A", "text": "224.0.0.0/8", "is_correct": false}, {"id": "B", "text": "232.0.0.0/8", "is_correct": true}, {"id": "C", "text": "239.0.0.0/8", "is_correct": false}, {"id": "D", "text": "233.0.0.0/8", "is_correct": false}]$$::jsonb, $$SSM uses the 232.0.0.0/8 range. 239.0.0.0/8 is administratively scoped.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Multicast$$::text, 7.0, '9f380f0fd20a05eb', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b5b02324-6f3b-5f28-aceb-70b4b44b3483', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', $$Which protocol is used by hosts to inform routers of multicast group membership?$$::text, $$[{"id": "A", "text": "PIM", "is_correct": false}, {"id": "B", "text": "IGMP", "is_correct": true}, {"id": "C", "text": "MSDP", "is_correct": false}, {"id": "D", "text": "MBGP", "is_correct": false}]$$::jsonb, $$IGMP is used between hosts and local routers to manage multicast group membership. PIM is router-to-router.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Multicast$$::text, 7.0, 'fb379df5bf3b9dd3', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('26aab2d9-aa6a-5a4c-bc21-45a050a2bde0', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which CoS component marks traffic at the edge of the network?$$::text, $$[{"id": "A", "text": "Scheduler", "is_correct": false}, {"id": "B", "text": "Classifier", "is_correct": true}, {"id": "C", "text": "Drop profile", "is_correct": false}, {"id": "D", "text": "Rewrite rule", "is_correct": false}]$$::jsonb, $$Classifiers examine incoming traffic and assign it to forwarding classes. Rewrite rules mark outgoing traffic.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$CoS$$::text, 5.0, '078f710338f35c38', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f6e916b6-4a9d-52b0-8c84-a6de24354596', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which CoS component determines how much bandwidth a forwarding class receives?$$::text, $$[{"id": "A", "text": "Classifier", "is_correct": false}, {"id": "B", "text": "Scheduler", "is_correct": true}, {"id": "C", "text": "Rewrite rule", "is_correct": false}, {"id": "D", "text": "Policer", "is_correct": false}]$$::jsonb, $$Schedulers define bandwidth, buffer, and priority for forwarding classes.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$CoS$$::text, 5.0, '8ef393c5c3dd0fb7', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df496095-036f-5f17-a949-2f79a43d7085', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which Junos feature limits traffic to a specified rate and drops excess?$$::text, $$[{"id": "A", "text": "Shaper", "is_correct": false}, {"id": "B", "text": "Policer", "is_correct": true}, {"id": "C", "text": "Scheduler", "is_correct": false}, {"id": "D", "text": "Rewrite rule", "is_correct": false}]$$::jsonb, $$Policers rate-limit traffic and drop or mark excess traffic. Shapers buffer and smooth traffic.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$CoS$$::text, 5.0, 'fcc78af85a1da6d6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('7bb82231-d004-5e0e-8103-b26a3465970b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which Segment Routing data plane uses MPLS labels without LDP or RSVP?$$::text, $$[{"id": "A", "text": "SRv6", "is_correct": false}, {"id": "B", "text": "SR-MPLS", "is_correct": true}, {"id": "C", "text": "RSVP-TE", "is_correct": false}, {"id": "D", "text": "LDP", "is_correct": false}]$$::jsonb, $$SR-MPLS uses the MPLS data plane with segment labels, eliminating the need for LDP or RSVP in some deployments.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Segment Routing$$::text, 5.0, '2c6f5ada9005dff4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('430d0dce-613a-5dd9-a247-4f943a1f4485', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', $$Which Junos automation tool uses YAML-based playbooks?$$::text, $$[{"id": "A", "text": "Ansible", "is_correct": true}, {"id": "B", "text": "Chef", "is_correct": false}, {"id": "C", "text": "Puppet", "is_correct": false}, {"id": "D", "text": "SaltStack", "is_correct": false}]$$::jsonb, $$Ansible uses YAML playbooks. Puppet uses its own DSL, Chef uses Ruby, and SaltStack uses YAML with different architecture.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Automation$$::text, 5.0, '2292f2f39c8fdd49', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5d1e09d9-2fe7-563c-a8fd-6886ba92f736', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which NETCONF operation retrieves configuration data?$$::text, $$[{"id": "A", "text": "<edit-config>", "is_correct": false}, {"id": "B", "text": "<get-config>", "is_correct": true}, {"id": "C", "text": "<copy-config>", "is_correct": false}, {"id": "D", "text": "<delete-config>", "is_correct": false}]$$::jsonb, $$NETCONF <get-config> retrieves configuration. <edit-config> modifies it, <copy-config> copies it, <delete-config> deletes it.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Automation$$::text, 5.0, 'cbc7d471b0303b4c', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b67f733f-fd95-5a8a-8126-a20420fca2a2', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which OSPF stub area type allows external routes to be advertised as Type 7 LSAs?$$::text, $$[{"id": "A", "text": "Stub", "is_correct": false}, {"id": "B", "text": "Totally stubby", "is_correct": false}, {"id": "C", "text": "NSSA", "is_correct": true}, {"id": "D", "text": "Standard", "is_correct": false}]$$::jsonb, $$NSSA (Not-So-Stubby Area) allows external routes to be advertised as Type 7 LSAs, which are converted to Type 5 at the ABR.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, '739e4b9bd2766c39', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('11a6709f-3839-59bd-a2ea-a42d6e864b02', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which OSPF area can contain virtual links?$$::text, $$[{"id": "A", "text": "Any area", "is_correct": false}, {"id": "B", "text": "Only the backbone area (Area 0)", "is_correct": true}, {"id": "C", "text": "Only stub areas", "is_correct": false}, {"id": "D", "text": "Only NSSA areas", "is_correct": false}]$$::jsonb, $$Virtual links in OSPF transit the backbone area (Area 0) and are used to connect discontiguous areas.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, '20ed2b170791fbf2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6b1e55a4-4a2f-5036-9829-f67021db65c7', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', $$Which Junos command configures OSPF authentication using MD5?$$::text, $$[{"id": "A", "text": "set protocols ospf area 0 authentication md5", "is_correct": false}, {"id": "B", "text": "set protocols ospf area 0 interface ge-0/0/0 authentication md5", "is_correct": true}, {"id": "C", "text": "set protocols ospf md5-key", "is_correct": false}, {"id": "D", "text": "set ospf authentication md5", "is_correct": false}]$$::jsonb, $$OSPF authentication is configured per interface under the area. Junos supports simple-password and MD5 authentication.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, '998249f442beeaf0', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f9792d83-860a-5d09-afdb-1a834fb689f3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which OSPF timer must match between neighbors for an adjacency to form?$$::text, $$[{"id": "A", "text": "Hello and Dead intervals", "is_correct": true}, {"id": "B", "text": "LSA refresh interval", "is_correct": false}, {"id": "C", "text": "SPF delay", "is_correct": false}, {"id": "D", "text": "DR election priority", "is_correct": false}]$$::jsonb, $$OSPF neighbors must agree on Hello and Dead intervals. Other timers can differ.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, '0b8c5921747d3d9a', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c0bb5111-06cb-56df-a9ff-1f38bf184e9c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'apply', $$Which command shows OSPF database summary LSAs?$$::text, $$[{"id": "A", "text": "show ospf database summary", "is_correct": true}, {"id": "B", "text": "show ospf database detail", "is_correct": false}, {"id": "C", "text": "show ospf database router", "is_correct": false}, {"id": "D", "text": "show ospf database network", "is_correct": false}]$$::jsonb, $$'show ospf database summary' displays Type 3 summary LSAs originated by ABRs.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, 'b46c61c88bcc7dd2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0d12b913-557f-532b-a2b8-13d06068ab2e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$What is the OSPF default reference bandwidth on Junos?$$::text, $$[{"id": "A", "text": "100 Mbps", "is_correct": false}, {"id": "B", "text": "1 Gbps", "is_correct": false}, {"id": "C", "text": "100 Gbps", "is_correct": true}, {"id": "D", "text": "10 Mbps", "is_correct": false}]$$::jsonb, $$Modern Junos uses a default OSPF reference bandwidth of 100 Gbps. Older defaults were 100 Mbps, often requiring adjustment.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, '03f4d9f9950a9398', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('cee932e9-75f8-58fa-8869-e33453d1a156', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which OSPF area type blocks both Type 5 external and Type 3 summary LSAs?$$::text, $$[{"id": "A", "text": "Stub", "is_correct": false}, {"id": "B", "text": "Totally stubby area", "is_correct": true}, {"id": "C", "text": "NSSA", "is_correct": false}, {"id": "D", "text": "Standard", "is_correct": false}]$$::jsonb, $$Totally stubby areas block both Type 5 external and Type 3 summary LSAs, relying on a default route.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, 'ee121d0d78d7eb83', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fa1f88dd-ac39-5888-8ce1-bd36a62d5167', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'apply', $$Which Junos command configures an OSPF stub area?$$::text, $$[{"id": "A", "text": "set protocols ospf area 0 stub", "is_correct": false}, {"id": "B", "text": "set protocols ospf area 0.0.0.1 stub", "is_correct": true}, {"id": "C", "text": "set protocols ospf stub area 1", "is_correct": false}, {"id": "D", "text": "set ospf area 1 stub", "is_correct": false}]$$::jsonb, $$OSPF areas are configured under 'set protocols ospf area <id> stub' in Junos.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, 'ae7692e27d5229cd', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('43258053-f5ca-55a1-918c-fe1f79b7715e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'remember', $$Which IS-IS TLV carries IPv6 reachability?$$::text, $$[{"id": "A", "text": "IP Internal Reachability", "is_correct": false}, {"id": "B", "text": "IPv6 Reachability", "is_correct": true}, {"id": "C", "text": "Extended IP Reachability", "is_correct": false}, {"id": "D", "text": "Protocols Supported", "is_correct": false}]$$::jsonb, $$IS-IS uses the IPv6 Reachability TLV (TLV 236) to carry IPv6 prefixes.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$IS-IS$$::text, 10.0, 'c991a3c14e0fa740', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('012b0727-fc64-5c9c-92ec-056a29a5ab82', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', $$Which command enables IS-IS wide metrics on both levels?$$::text, $$[{"id": "A", "text": "set protocols isis level 1 wide-metrics-only and set protocols isis level 2 wide-metrics-only", "is_correct": true}, {"id": "B", "text": "set protocols isis wide-metrics", "is_correct": false}, {"id": "C", "text": "set protocols isis interface all metric wide", "is_correct": false}, {"id": "D", "text": "set protocols isis level 1/2 wide-metrics", "is_correct": false}]$$::jsonb, $$Wide metrics are enabled separately per IS-IS level with 'wide-metrics-only'.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$IS-IS$$::text, 10.0, 'e224412ad6665ac8', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('199e7a58-c3aa-51cf-bd7e-fffe25d9ee35', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which IS-IS level routes traffic between areas?$$::text, $$[{"id": "A", "text": "Level 1", "is_correct": false}, {"id": "B", "text": "Level 2", "is_correct": true}, {"id": "C", "text": "Level 1/2", "is_correct": false}, {"id": "D", "text": "Level 0", "is_correct": false}]$$::jsonb, $$IS-IS Level 2 routers know the inter-area topology and route traffic between areas.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$IS-IS$$::text, 10.0, 'b80abb6fc6e150ef', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54acc237-d6ef-5401-b18d-172829b84b65', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which command displays IS-IS link-state database?$$::text, $$[{"id": "A", "text": "show isis database", "is_correct": true}, {"id": "B", "text": "show isis lsdb", "is_correct": false}, {"id": "C", "text": "show isis route", "is_correct": false}, {"id": "D", "text": "show isis topology", "is_correct": false}]$$::jsonb, $$'show isis database' displays the IS-IS link-state database.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$IS-IS$$::text, 10.0, '0476809a52f81c0b', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9485def7-15f6-5f20-9dae-e967dd871768', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which authentication type can be configured for IS-IS PDUs?$$::text, $$[{"id": "A", "text": "None, simple, and MD5", "is_correct": true}, {"id": "B", "text": "Only MD5", "is_correct": false}, {"id": "C", "text": "Only simple", "is_correct": false}, {"id": "D", "text": "Only SHA", "is_correct": false}]$$::jsonb, $$Junos IS-IS supports none, simple, and MD5 authentication for PDUs.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$IS-IS$$::text, 10.0, 'd06f06fde91f9c92', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('8482d41c-70fb-5934-9cf3-b0ea20b4493e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which BGP well-known community makes a route never advertised outside the local AS?$$::text, $$[{"id": "A", "text": "no-export", "is_correct": true}, {"id": "B", "text": "no-advertise", "is_correct": false}, {"id": "C", "text": "internet", "is_correct": false}, {"id": "D", "text": "local-AS", "is_correct": false}]$$::jsonb, $$The NO_EXPORT community prevents a route from being advertised to eBGP peers. NO_ADVERTISE prevents any advertisement.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, '09a76c73151ad1e7', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef57191a-c878-59d7-801b-f77458007f08', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which BGP community prevents a route from being advertised to any peer?$$::text, $$[{"id": "A", "text": "no-export", "is_correct": false}, {"id": "B", "text": "no-advertise", "is_correct": true}, {"id": "C", "text": "internet", "is_correct": false}, {"id": "D", "text": "no-peer", "is_correct": false}]$$::jsonb, $$The NO_ADVERTISE community prevents a route from being advertised to any BGP peer, including iBGP.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, '84d0a6562b5dc6f7', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9185066d-e73f-5a59-83c3-609c7987f1fe', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'apply', $$Which command displays BGP routes received from a specific neighbor?$$::text, $$[{"id": "A", "text": "show route receive-protocol bgp <neighbor>", "is_correct": true}, {"id": "B", "text": "show bgp neighbor <neighbor> routes", "is_correct": false}, {"id": "C", "text": "show route advertising-protocol bgp <neighbor>", "is_correct": false}, {"id": "D", "text": "show bgp routes <neighbor>", "is_correct": false}]$$::jsonb, $$'show route receive-protocol bgp <neighbor>' displays routes received from a BGP peer.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, '93d5bafa2b15428d', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e3161f59-e3d5-549a-b38a-9144ed674184', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'apply', $$Which command displays BGP routes advertised to a specific neighbor?$$::text, $$[{"id": "A", "text": "show route receive-protocol bgp <neighbor>", "is_correct": false}, {"id": "B", "text": "show route advertising-protocol bgp <neighbor>", "is_correct": true}, {"id": "C", "text": "show bgp advertised-routes", "is_correct": false}, {"id": "D", "text": "show bgp export <neighbor>", "is_correct": false}]$$::jsonb, $$'show route advertising-protocol bgp <neighbor>' displays routes sent to a BGP peer.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, 'c74b847cae9544ff', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('772fe22e-5252-56d5-a1a9-bf905ad37113', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which BGP path attribute identifies the router that originally injected a route into BGP?$$::text, $$[{"id": "A", "text": "Router ID", "is_correct": false}, {"id": "B", "text": "Cluster ID", "is_correct": false}, {"id": "C", "text": "Originator ID", "is_correct": true}, {"id": "D", "text": "Peer ID", "is_correct": false}]$$::jsonb, $$Originator ID identifies the BGP router that originally advertised a route into an RR cluster.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, '991c33a8d573aeb4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('36dbb64d-a751-5447-84e6-6d57f988b2d3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', $$Which Junos policy action removes private AS numbers from the AS Path?$$::text, $$[{"id": "A", "text": "remove-private", "is_correct": true}, {"id": "B", "text": "strip-private-as", "is_correct": false}, {"id": "C", "text": "delete-private", "is_correct": false}, {"id": "D", "text": "as-path-delete", "is_correct": false}]$$::jsonb, $$'remove-private' in a Junos export policy strips private AS numbers before advertising to eBGP peers.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, '2b76a039f5d35c4e', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('470bf8cb-98c0-5b02-967d-86a2808280ed', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which BGP feature allows a router to advertise multiple paths for load balancing?$$::text, $$[{"id": "A", "text": "Multipath", "is_correct": false}, {"id": "B", "text": "Add-path", "is_correct": true}, {"id": "C", "text": "Route reflector", "is_correct": false}, {"id": "D", "text": "Confederation", "is_correct": false}]$$::jsonb, $$BGP add-path allows a router to advertise multiple paths for the same prefix, enabling receiver-side multipath.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, '847f52f6b95d1be2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b43d6231-49e6-58be-9d5b-41909dd38111', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', $$Which command enables BGP multipath for a specific number of paths?$$::text, $$[{"id": "A", "text": "set protocols bgp multipath multiple-as", "is_correct": false}, {"id": "B", "text": "set protocols bgp group <name> multipath", "is_correct": true}, {"id": "C", "text": "set routing-options multipath bgp", "is_correct": false}, {"id": "D", "text": "set protocols bgp add-path", "is_correct": false}]$$::jsonb, $$BGP multipath is enabled per group with 'multipath'. 'multiple-as' allows paths from different ASes.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, 'f6d1a329d8dd2d04', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('6406e85c-227b-5483-96af-1dd8de2ab9cf', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', $$Which BGP message is sent when an error is detected?$$::text, $$[{"id": "A", "text": "Open", "is_correct": false}, {"id": "B", "text": "Update", "is_correct": false}, {"id": "C", "text": "Keepalive", "is_correct": false}, {"id": "D", "text": "Notification", "is_correct": true}]$$::jsonb, $$BGP Notification messages are sent when errors are detected and cause the session to close.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, '50537db3aaa2d3f2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0c3262c6-720e-52be-b256-7c2e01060eca', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which RSVP object specifies the explicit path of an LSP?$$::text, $$[{"id": "A", "text": "SESSION", "is_correct": false}, {"id": "B", "text": "EXPLICIT_ROUTE", "is_correct": true}, {"id": "C", "text": "LABEL_REQUEST", "is_correct": false}, {"id": "D", "text": "SENDER_TEMPLATE", "is_correct": false}]$$::jsonb, $$The RSVP ERO (Explicit Route Object) defines the path an LSP should take through the network.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, '1a1b75eaec0ca553', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('00da3d27-5518-57c7-b5ad-afb550c33e59', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which Junos command displays RSVP neighbors?$$::text, $$[{"id": "A", "text": "show rsvp neighbor", "is_correct": true}, {"id": "B", "text": "show rsvp session", "is_correct": false}, {"id": "C", "text": "show mpls rsvp", "is_correct": false}, {"id": "D", "text": "show rsvp interface", "is_correct": false}]$$::jsonb, $$'show rsvp neighbor' displays RSVP neighbors and their states.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, 'f8747637be81777d', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('f87fa605-69ec-55a1-b709-d5a3fd81803f', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which MPLS application uses a directed LDP session to transport pseudowires?$$::text, $$[{"id": "A", "text": "Layer 3 VPN", "is_correct": false}, {"id": "B", "text": "Layer 2 VPN", "is_correct": true}, {"id": "C", "text": "Traffic engineering", "is_correct": false}, {"id": "D", "text": "6PE", "is_correct": false}]$$::jsonb, $$Layer 2 VPNs and VPLS often use targeted LDP sessions to signal pseudowire labels.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, 'd2346db94d1160a4', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('54c7e5f7-b306-5a6d-95c0-8bee84241818', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'apply', $$Which command shows the MPLS label binding for a specific FEC?$$::text, $$[{"id": "A", "text": "show ldp database", "is_correct": true}, {"id": "B", "text": "show ldp session", "is_correct": false}, {"id": "C", "text": "show mpls lsp", "is_correct": false}, {"id": "D", "text": "show route forwarding-table", "is_correct": false}]$$::jsonb, $$'show ldp database' displays LDP label bindings (FEC-to-label mappings).$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, 'cd42e1c88f24bb49', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('c9e0dc72-55a0-532b-9ed2-e21c785547e9', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$What is the purpose of the RSVP bandwidth statement on an LSP?$$::text, $$[{"id": "A", "text": "To set the IGP metric", "is_correct": false}, {"id": "B", "text": "To reserve bandwidth along the path", "is_correct": true}, {"id": "C", "text": "To enable LDP", "is_correct": false}, {"id": "D", "text": "To configure PHP", "is_correct": false}]$$::jsonb, $$The RSVP bandwidth statement reserves bandwidth for the LSP, used by CSPF for traffic-engineered paths.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, 'e863f7d457e7890d', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e15eea2d-e23b-557e-ab3a-098ea37e3947', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which MPLS protection mechanism creates a pre-signaled backup path?$$::text, $$[{"id": "A", "text": "Facility backup / Fast Reroute", "is_correct": true}, {"id": "B", "text": "Link protection only", "is_correct": false}, {"id": "C", "text": "BFD", "is_correct": false}, {"id": "D", "text": "LDP graceful restart", "is_correct": false}]$$::jsonb, $$MPLS Fast Reroute (FRR) with facility backup pre-computes and pre-signals backup paths for rapid failover.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, '332f10172f3f7dcb', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('34270f7e-cf5d-5c4c-8630-3424d8a95263', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which extended community is used to tag VPN routes for import/export?$$::text, $$[{"id": "A", "text": "Route Distinguisher", "is_correct": false}, {"id": "B", "text": "Route Target", "is_correct": true}, {"id": "C", "text": "Site of Origin", "is_correct": false}, {"id": "D", "text": "Cluster List", "is_correct": false}]$$::jsonb, $$Route Target (RT) extended communities determine which VRFs import and export VPN routes.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Layer 3 VPNs$$::text, 10.0, '6ca3610f0c784bee', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fd3135e4-f457-5d0c-bf90-6867f82a2c7d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which interprovider VPN option exchanges VPN-IPv4 routes directly between ASBRs?$$::text, $$[{"id": "A", "text": "Option A", "is_correct": false}, {"id": "B", "text": "Option B", "is_correct": true}, {"id": "C", "text": "Option C", "is_correct": false}, {"id": "D", "text": "Option D", "is_correct": false}]$$::jsonb, $$Option B uses MP-eBGP between ASBRs to exchange VPN-IPv4 routes. Option A uses VRF-to-VRF interfaces, Option C uses multihop MP-eBGP.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Layer 3 VPNs$$::text, 10.0, '34170f05d140a881', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0fdd7431-aa19-512c-a495-af00ded9516b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'apply', $$Which command displays VPN routing instance routes?$$::text, $$[{"id": "A", "text": "show route table <instance>.inet.0", "is_correct": true}, {"id": "B", "text": "show route vpn", "is_correct": false}, {"id": "C", "text": "show vrf routes", "is_correct": false}, {"id": "D", "text": "show routing-instances route", "is_correct": false}]$$::jsonb, $$VRF routes are stored in tables named <routing-instance>.inet.0.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Layer 3 VPNs$$::text, 10.0, '31324561f814b083', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('e644bbd2-629e-54c8-aaf0-66b3bc0e084d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$What is the purpose of Site of Origin (SoO)?$$::text, $$[{"id": "A", "text": "To make prefixes unique in MP-BGP", "is_correct": false}, {"id": "B", "text": "To prevent routing loops when a site is multihomed", "is_correct": true}, {"id": "C", "text": "To encrypt VPN traffic", "is_correct": false}, {"id": "D", "text": "To establish BGP sessions", "is_correct": false}]$$::jsonb, $$Site of Origin (SoO) identifies the originating site and prevents routes from being readvertised back to the same site.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Layer 3 VPNs$$::text, 10.0, 'fcbfa75b30837be2', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('01c2ce8c-3940-55ba-83b8-d70eb7086746', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which PIM mode builds source-based trees after initial registration?$$::text, $$[{"id": "A", "text": "PIM-DM", "is_correct": false}, {"id": "B", "text": "PIM-SM", "is_correct": true}, {"id": "C", "text": "PIM-SSM", "is_correct": false}, {"id": "D", "text": "Bidir-PIM", "is_correct": false}]$$::jsonb, $$PIM-SM initially uses a shared tree toward the RP and can switch to a shortest-path tree (SPT) toward the source.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Multicast$$::text, 7.0, '11f1be9efe018fda', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eadfff7f-8b8c-5ef8-b80f-1c6ec73c7e31', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which protocol is used between PIM domains to discover active sources?$$::text, $$[{"id": "A", "text": "IGMP", "is_correct": false}, {"id": "B", "text": "MSDP", "is_correct": true}, {"id": "C", "text": "MBGP", "is_correct": false}, {"id": "D", "text": "PIM Register", "is_correct": false}]$$::jsonb, $$MSDP (Multicast Source Discovery Protocol) exchanges active source information between PIM domains and RPs.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Multicast$$::text, 7.0, '1439257f4caacf7d', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('a84607f3-3d24-5971-9417-2e8048dcede6', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which Junos command shows PIM neighbors?$$::text, $$[{"id": "A", "text": "show pim neighbors", "is_correct": true}, {"id": "B", "text": "show pim interface", "is_correct": false}, {"id": "C", "text": "show multicast route", "is_correct": false}, {"id": "D", "text": "show pim join", "is_correct": false}]$$::jsonb, $$'show pim neighbors' displays discovered PIM neighbors and their interfaces.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Multicast$$::text, 7.0, '24a999d477238d34', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0caea830-c84f-57e3-a140-a9f5bda09958', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which IGMP version supports source filtering for SSM?$$::text, $$[{"id": "A", "text": "IGMPv1", "is_correct": false}, {"id": "B", "text": "IGMPv2", "is_correct": false}, {"id": "C", "text": "IGMPv3", "is_correct": true}, {"id": "D", "text": "IGMPv4", "is_correct": false}]$$::jsonb, $$IGMPv3 supports source-specific multicast and source filtering required for SSM.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Multicast$$::text, 7.0, 'b09fe056cef35d70', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('42c4c205-6168-55df-9d74-1c0346c71ac1', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'apply', $$Which command verifies the MPLS label path taken by packets to a destination?$$::text, $$[{"id": "A", "text": "traceroute mpls ipv4", "is_correct": true}, {"id": "B", "text": "ping mpls", "is_correct": false}, {"id": "C", "text": "show mpls lsp", "is_correct": false}, {"id": "D", "text": "show route forwarding-table", "is_correct": false}]$$::jsonb, $$'traceroute mpls ipv4' traces the MPLS label-switched path to a destination.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Troubleshooting$$::text, 5.0, 'b1ac25d03cd222bf', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('95fa8376-9cd0-53f1-86ea-b6d5469c2b16', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which command checks BGP session state and message counts?$$::text, $$[{"id": "A", "text": "show bgp summary", "is_correct": true}, {"id": "B", "text": "show route summary", "is_correct": false}, {"id": "C", "text": "show protocols bgp", "is_correct": false}, {"id": "D", "text": "show system connections", "is_correct": false}]$$::jsonb, $$'show bgp summary' shows BGP peer states, AS numbers, received/sent messages, and prefixes.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '2f9c62b56989f221', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d4e5bf1f-8882-56de-9e55-c28a2c4947b3', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which command displays interface errors and drops?$$::text, $$[{"id": "A", "text": "show interfaces extensive", "is_correct": true}, {"id": "B", "text": "show interfaces terse", "is_correct": false}, {"id": "C", "text": "show route interface", "is_correct": false}, {"id": "D", "text": "show chassis fpc", "is_correct": false}]$$::jsonb, $$'show interfaces extensive' displays detailed interface statistics including errors and drops.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '2d17a172d61652ad', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3c646c05-eeb5-54d8-b0a8-b951a19d043c', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'apply', $$Which Junos utility tests MPLS connectivity using ICMP?$$::text, $$[{"id": "A", "text": "ping mpls", "is_correct": true}, {"id": "B", "text": "traceroute mpls", "is_correct": false}, {"id": "C", "text": "monitor mpls", "is_correct": false}, {"id": "D", "text": "test mpls", "is_correct": false}]$$::jsonb, $$'ping mpls' tests MPLS data-plane connectivity, similar to IP ping but through an LSP.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '774cb583a400d7d8', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('4d7c738d-6cb6-557b-932c-fb68ccdca02d', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which command displays the current routing table for a specific protocol?$$::text, $$[{"id": "A", "text": "show route protocol <protocol>", "is_correct": true}, {"id": "B", "text": "show route table", "is_correct": false}, {"id": "C", "text": "show protocols route", "is_correct": false}, {"id": "D", "text": "show forwarding-table", "is_correct": false}]$$::jsonb, $$'show route protocol <protocol>' filters the routing table to show routes learned from a specific protocol.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Troubleshooting$$::text, 5.0, 'e59b2c1cbd38410d', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('5fc27cd5-5933-58fc-bf25-f1495614015a', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'apply', $$Which Junos command shows the current BGP path selection process?$$::text, $$[{"id": "A", "text": "show bgp summary", "is_correct": false}, {"id": "B", "text": "show route <prefix> detail", "is_correct": true}, {"id": "C", "text": "show bgp neighbor", "is_correct": false}, {"id": "D", "text": "show route protocol bgp", "is_correct": false}]$$::jsonb, $$'show route <prefix> detail' shows why a specific BGP path was selected, including path attributes.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, 'c68ee295a62a8990', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('30b3fe01-1e49-5faa-84cc-6c47b1d8c366', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'analyze', $$In Junos BGP path selection, which attribute is compared immediately after the Origin attribute?$$::text, $$[{"id": "A", "text": "MED", "is_correct": true}, {"id": "B", "text": "Local Preference", "is_correct": false}, {"id": "C", "text": "AS Path", "is_correct": false}, {"id": "D", "text": "IGP metric", "is_correct": false}]$$::jsonb, $$Junos BGP path selection order: weight, local preference, local origin, AS path, origin, MED, eBGP/iBGP, IGP metric, router ID.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, '492bbae5e66dbdc1', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('3b52d4e9-831d-5cdf-8fad-0f94550f7a0b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$What is the function of the RSVP SENDER_TSPEC object?$$::text, $$[{"id": "A", "text": "To specify the sender's traffic characteristics", "is_correct": true}, {"id": "B", "text": "To define the explicit route", "is_correct": false}, {"id": "C", "text": "To request labels", "is_correct": false}, {"id": "D", "text": "To reserve bandwidth", "is_correct": false}]$$::jsonb, $$SENDER_TSPEC describes the traffic parameters of the sender in RSVP Path messages.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, '41599596222eff97', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef386535-b54f-5d82-bfdd-55af691db6df', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which LDP feature advertises labels for all IGP prefixes automatically?$$::text, $$[{"id": "A", "text": "LDP ingress", "is_correct": false}, {"id": "B", "text": "LDP egress", "is_correct": false}, {"id": "C", "text": "LDP transit", "is_correct": false}, {"id": "D", "text": "LDP is enabled by default when configured on interfaces", "is_correct": true}]$$::jsonb, $$When LDP is enabled on interfaces, it automatically advertises labels for all IGP-learned prefixes.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, 'ccc066f9b3d23d2a', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('efb3f260-1c8b-5bb9-9a7b-55e41e4bf843', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which command verifies the LDP session state?$$::text, $$[{"id": "A", "text": "show ldp session", "is_correct": true}, {"id": "B", "text": "show ldp neighbor", "is_correct": false}, {"id": "C", "text": "show ldp interface", "is_correct": false}, {"id": "D", "text": "show mpls ldp", "is_correct": false}]$$::jsonb, $$'show ldp session' displays LDP neighbor sessions, state, and address families.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, '36d9a43e00935905', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('df427f0f-0b8e-5673-b1d3-39c4c95e0ef7', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which Junos feature protects an MPLS LSP by pre-signaling a backup path?$$::text, $$[{"id": "A", "text": "Link protection", "is_correct": false}, {"id": "B", "text": "Node-link protection", "is_correct": false}, {"id": "C", "text": "Fast Reroute", "is_correct": true}, {"id": "D", "text": "BFD", "is_correct": false}]$$::jsonb, $$MPLS Fast Reroute pre-signals backup paths to protect against link or node failures.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, '63e46cdc3d43cd11', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('416df897-942a-5e6f-beb3-e64433a98749', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which command displays the IPv6 routing table?$$::text, $$[{"id": "A", "text": "show route table inet6.0", "is_correct": true}, {"id": "B", "text": "show route ipv6", "is_correct": false}, {"id": "C", "text": "show route table inet.0", "is_correct": false}, {"id": "D", "text": "show ipv6 route", "is_correct": false}]$$::jsonb, $$Junos stores IPv6 routes in the inet6.0 routing table. inet.0 is for IPv4.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '685e2e0562a328ce', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('70956d14-8fbf-509c-9e19-646d51d0072e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which command shows active alarms and why the chassis alarm LED is on?$$::text, $$[{"id": "A", "text": "show system alarms", "is_correct": true}, {"id": "B", "text": "show chassis alarms", "is_correct": false}, {"id": "C", "text": "show log messages", "is_correct": false}, {"id": "D", "text": "show system led", "is_correct": false}]$$::jsonb, $$'show system alarms' displays active red and yellow alarms on Junos.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Troubleshooting$$::text, 5.0, 'bace5cb833cf527e', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('eaed554c-35ca-5bbc-a0d5-0537f9244452', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which OSPF neighbor state indicates that DBDs have been exchanged but LSDBs are not fully synchronized?$$::text, $$[{"id": "A", "text": "Exchange", "is_correct": true}, {"id": "B", "text": "Loading", "is_correct": false}, {"id": "C", "text": "Full", "is_correct": false}, {"id": "D", "text": "2-Way", "is_correct": false}]$$::jsonb, $$In Exchange state, routers exchange DBD packets. Loading state requests missing LSAs. Full state means synchronization.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, '01030b1ab5318f34', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('fdb4afff-370f-5b64-8eb5-612c7466c4a6', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'remember', $$Which IS-IS PDU requests a specific LSA from a neighbor?$$::text, $$[{"id": "A", "text": "CSNP", "is_correct": false}, {"id": "B", "text": "PSNP", "is_correct": true}, {"id": "C", "text": "LSP", "is_correct": false}, {"id": "D", "text": "IIH", "is_correct": false}]$$::jsonb, $$Partial Sequence Number PDUs (PSNPs) request specific LSPs or acknowledge receipt on point-to-point links.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$IS-IS$$::text, 10.0, 'ffe6e60928f59f07', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('0e1c7b5f-5145-5d9a-a4f7-55f1c36a9dd0', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which BGP attribute indicates how a route was originally injected into BGP?$$::text, $$[{"id": "A", "text": "Origin", "is_correct": true}, {"id": "B", "text": "AS Path", "is_correct": false}, {"id": "C", "text": "Next Hop", "is_correct": false}, {"id": "D", "text": "MED", "is_correct": false}]$$::jsonb, $$The Origin attribute indicates whether a route was originated via IGP, EGP, or incomplete.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, 'f1c98c48c9b975a0', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('96e21369-2153-5f28-89e2-3fec93a8cbbe', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 3, 'understand', $$Which MPLS application uses BGP labeled unicast to build end-to-end LSPs?$$::text, $$[{"id": "A", "text": "Layer 3 VPN", "is_correct": false}, {"id": "B", "text": "Layer 2 VPN", "is_correct": false}, {"id": "C", "text": "Interdomain MPLS / BGP-LU", "is_correct": true}, {"id": "D", "text": "VPLS", "is_correct": false}]$$::jsonb, $$BGP labeled unicast (BGP-LU) distributes MPLS labels for prefixes, enabling interdomain MPLS LSPs.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, '9c42d6a45eb118bc', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('d5d2237a-3afe-5521-9a5b-c343cb91b540', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'apply', $$Which Junos command shows the forwarding table for a specific routing instance?$$::text, $$[{"id": "A", "text": "show route forwarding-table instance <name>", "is_correct": true}, {"id": "B", "text": "show forwarding-table instance <name>", "is_correct": false}, {"id": "C", "text": "show route table <name>", "is_correct": false}, {"id": "D", "text": "show instance forwarding", "is_correct": false}]$$::jsonb, $$'show route forwarding-table instance <name>' displays the forwarding table for a specific routing instance.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '2314a59aa49ce768', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ed93d67d-1d7e-572e-b9fb-bcdeb38fd73e', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which multicast protocol is used for inter-domain source discovery?$$::text, $$[{"id": "A", "text": "MSDP", "is_correct": true}, {"id": "B", "text": "PIM", "is_correct": false}, {"id": "C", "text": "IGMP", "is_correct": false}, {"id": "D", "text": "MBGP", "is_correct": false}]$$::jsonb, $$MSDP is used between RPs in different PIM domains to discover active sources.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Multicast$$::text, 7.0, '90aa9fd1d8495587', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('93941d3b-8ffe-5181-83cf-1fc3741055d7', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'understand', $$Which CoS component maps outgoing traffic to DSCP or IEEE 802.1p values?$$::text, $$[{"id": "A", "text": "Classifier", "is_correct": false}, {"id": "B", "text": "Rewrite rule", "is_correct": true}, {"id": "C", "text": "Scheduler", "is_correct": false}, {"id": "D", "text": "Drop profile", "is_correct": false}]$$::jsonb, $$Rewrite rules modify outgoing packet markings such as DSCP or 802.1p.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$CoS$$::text, 5.0, '5691321821e4c25b', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('ef338498-0d3d-587f-83e4-b15e7f266e74', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which command displays the Junos configuration as a series of set commands?$$::text, $$[{"id": "A", "text": "show configuration | display set", "is_correct": true}, {"id": "B", "text": "show config set", "is_correct": false}, {"id": "C", "text": "show | display set", "is_correct": false}, {"id": "D", "text": "display set configuration", "is_correct": false}]$$::jsonb, $$'show configuration | display set' outputs the active configuration in set command format.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '6379fb2541ca1109', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('615f48a0-c4b9-5ed6-90fc-0cf751aadda5', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', $$Which BGP message maintains the session between peers?$$::text, $$[{"id": "A", "text": "Open", "is_correct": false}, {"id": "B", "text": "Update", "is_correct": false}, {"id": "C", "text": "Keepalive", "is_correct": true}, {"id": "D", "text": "Notification", "is_correct": false}]$$::jsonb, $$BGP Keepalive messages maintain the session. If keepalives are not received, the session times out.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$BGP$$::text, 15.0, 'dd84b4cb67248df0', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('84f6b433-d374-56df-93f0-b06787beda20', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'apply', $$Which Junos command displays active system processes and CPU usage?$$::text, $$[{"id": "A", "text": "show system processes extensive", "is_correct": true}, {"id": "B", "text": "show chassis routing-engine", "is_correct": false}, {"id": "C", "text": "show system cpu", "is_correct": false}, {"id": "D", "text": "show process monitor", "is_correct": false}]$$::jsonb, $$'show system processes extensive' displays running processes and CPU/memory usage on the RE.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$Troubleshooting$$::text, 5.0, '89ac263e0d866a14', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bc004fcc-2214-54ab-b6ab-cd2935b11719', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which OSPF LSA type is generated by the DR on a multi-access network?$$::text, $$[{"id": "A", "text": "Type 1", "is_correct": false}, {"id": "B", "text": "Type 2", "is_correct": true}, {"id": "C", "text": "Type 3", "is_correct": false}, {"id": "D", "text": "Type 4", "is_correct": false}]$$::jsonb, $$Type 2 Network LSAs are generated by the DR on multi-access segments and list attached routers.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$OSPF$$::text, 10.0, '7efbbe95e3ba3ca6', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('b4ec6052-8869-55e5-8f35-0fecc4946625', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 2, 'remember', $$Which IS-IS metric style supports metrics larger than 63?$$::text, $$[{"id": "A", "text": "Narrow", "is_correct": false}, {"id": "B", "text": "Wide", "is_correct": true}, {"id": "C", "text": "Old", "is_correct": false}, {"id": "D", "text": "Legacy", "is_correct": false}]$$::jsonb, $$IS-IS wide metrics support a much larger metric range than narrow metrics.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$IS-IS$$::text, 10.0, '8f50431cb4ca384e', true) ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('bdf239a6-7ce5-5091-b756-6206147a5b5f', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 1, 'remember', $$Which MPLS label distribution protocol uses TCP port 646?$$::text, $$[{"id": "A", "text": "LDP", "is_correct": true}, {"id": "B", "text": "RSVP", "is_correct": false}, {"id": "C", "text": "BGP", "is_correct": false}, {"id": "D", "text": "IS-IS", "is_correct": false}]$$::jsonb, $$LDP uses TCP port 646. RSVP uses IP protocol 46.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$MPLS$$::text, 10.0, '011220342dd46534', true) ON CONFLICT (id) DO NOTHING;
